cat > /tmp/blk.php <<'EOF'
<?php
$theme = \Drupal::config('system.theme')->get('default');
echo "default theme: $theme\n";
$blocks = \Drupal::entityTypeManager()->getStorage('block')->loadByProperties(['theme'=>$theme]);
echo "blocks on $theme: " . count($blocks) . PHP_EOL;
$vis = [];
foreach ($blocks as $b) { $vis[$b->getRegion()] = ($vis[$b->getRegion()]??0)+1; }
foreach ($vis as $r=>$c) echo "  $r: $c\n";
EOF
cd /workspace && cp /tmp/blk.php /workspace/blk_tmp.php && su ddevuser -c "ddev drush php:script blk_tmp.php" 2>&1 | tail -15; rm -f /workspace/blk_tmp.php
